-- Read-only Supabase catalog drift fingerprints.
-- Run each SELECT independently against the intended project.
-- These statements read catalogs only; they perform no DDL/DML.

-- CLASS: public_tables
WITH rows AS (SELECT jsonb_build_object('schema',n.nspname,'name',c.relname,'kind',c.relkind,'owner',pg_catalog.pg_get_userbyid(c.relowner)) AS obj FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind IN ('r','p')), agg AS (SELECT count(*)::int AS n,coalesce(jsonb_agg(obj ORDER BY obj::text COLLATE "C"),'[]'::jsonb) AS j FROM rows) SELECT jsonb_build_object('class','public_tables','count',n,'md5',md5(j::text)) AS result FROM agg;

-- CLASS: public_columns
WITH rows AS (SELECT jsonb_build_object('table',c.relname,'position',a.attnum,'column',a.attname,'type',pg_catalog.format_type(a.atttypid,a.atttypmod),'not_null',a.attnotnull,'identity',a.attidentity,'generated',a.attgenerated,'default',pg_catalog.pg_get_expr(d.adbin,d.adrelid)) AS obj FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace JOIN pg_catalog.pg_attribute a ON a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped LEFT JOIN pg_catalog.pg_attrdef d ON d.adrelid=c.oid AND d.adnum=a.attnum WHERE n.nspname='public' AND c.relkind IN ('r','p')), agg AS (SELECT count(*)::int AS n,coalesce(jsonb_agg(obj ORDER BY obj::text COLLATE "C"),'[]'::jsonb) AS j FROM rows) SELECT jsonb_build_object('class','public_columns','count',n,'md5',md5(j::text)) AS result FROM agg;

-- CLASS: public_constraints
WITH rows AS (SELECT jsonb_build_object('table',c.relname,'name',con.conname,'kind',con.contype,'definition',pg_catalog.pg_get_constraintdef(con.oid,true),'validated',con.convalidated,'deferrable',con.condeferrable,'initially_deferred',con.condeferred) AS obj FROM pg_catalog.pg_constraint con JOIN pg_catalog.pg_class c ON c.oid=con.conrelid JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind IN ('r','p')), agg AS (SELECT count(*)::int AS n,coalesce(jsonb_agg(obj ORDER BY obj::text COLLATE "C"),'[]'::jsonb) AS j FROM rows) SELECT jsonb_build_object('class','public_constraints','count',n,'md5',md5(j::text)) AS result FROM agg;

-- CLASS: public_indexes
WITH rows AS (SELECT jsonb_build_object('table',t.relname,'name',i.relname,'definition',pg_catalog.pg_get_indexdef(i.oid),'valid',ix.indisvalid,'ready',ix.indisready,'unique',ix.indisunique,'primary',ix.indisprimary,'replica_identity',ix.indisreplident) AS obj FROM pg_catalog.pg_index ix JOIN pg_catalog.pg_class i ON i.oid=ix.indexrelid JOIN pg_catalog.pg_class t ON t.oid=ix.indrelid JOIN pg_catalog.pg_namespace n ON n.oid=t.relnamespace WHERE n.nspname='public' AND t.relkind IN ('r','p')), agg AS (SELECT count(*)::int AS n,coalesce(jsonb_agg(obj ORDER BY obj::text COLLATE "C"),'[]'::jsonb) AS j FROM rows) SELECT jsonb_build_object('class','public_indexes','count',n,'md5',md5(j::text)) AS result FROM agg;

-- CLASS: public_policies
WITH rows AS (SELECT jsonb_build_object('table',p.tablename,'rls_enabled',c.relrowsecurity,'force_rls',c.relforcerowsecurity,'name',p.policyname,'permissive',p.permissive,'roles',p.roles,'command',p.cmd,'using',p.qual,'with_check',p.with_check) AS obj FROM pg_catalog.pg_policies p JOIN pg_catalog.pg_class c ON c.relname=p.tablename JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace AND n.nspname=p.schemaname WHERE p.schemaname='public'), agg AS (SELECT count(*)::int AS n,coalesce(jsonb_agg(obj ORDER BY obj::text COLLATE "C"),'[]'::jsonb) AS j FROM rows) SELECT jsonb_build_object('class','public_policies','count',n,'md5',md5(j::text)) AS result FROM agg;

-- CLASS: public_rls_flags
WITH rows AS (SELECT jsonb_build_object('table',c.relname,'enabled',c.relrowsecurity,'forced',c.relforcerowsecurity) AS obj FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind IN ('r','p')), agg AS (SELECT count(*)::int AS n,coalesce(jsonb_agg(obj ORDER BY obj::text COLLATE "C"),'[]'::jsonb) AS j FROM rows) SELECT jsonb_build_object('class','public_rls_flags','count',n,'md5',md5(j::text)) AS result FROM agg;

-- CLASS: public_table_acl
WITH rows AS (SELECT jsonb_build_object('table',c.relname,'grantee',CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_catalog.pg_get_userbyid(a.grantee) END,'grantor',pg_catalog.pg_get_userbyid(a.grantor),'privilege',a.privilege_type,'grantable',a.is_grantable) AS obj FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace CROSS JOIN LATERAL pg_catalog.aclexplode(coalesce(c.relacl,pg_catalog.acldefault('r',c.relowner))) a WHERE n.nspname='public' AND c.relkind IN ('r','p') AND (a.grantee=0 OR pg_catalog.pg_get_userbyid(a.grantee) IN ('anon','authenticated','service_role'))), agg AS (SELECT count(*)::int AS n,coalesce(jsonb_agg(obj ORDER BY obj::text COLLATE "C"),'[]'::jsonb) AS j FROM rows) SELECT jsonb_build_object('class','public_table_acl','count',n,'md5',md5(j::text)) AS result FROM agg;

-- CLASS: public_column_acl
WITH rows AS (SELECT jsonb_build_object('table',c.relname,'column',a.attname,'grantee',CASE WHEN x.grantee=0 THEN 'PUBLIC' ELSE pg_catalog.pg_get_userbyid(x.grantee) END,'grantor',pg_catalog.pg_get_userbyid(x.grantor),'privilege',x.privilege_type,'grantable',x.is_grantable) AS obj FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace JOIN pg_catalog.pg_attribute a ON a.attrelid=c.oid AND a.attnum>0 AND NOT a.attisdropped CROSS JOIN LATERAL pg_catalog.aclexplode(a.attacl) x WHERE n.nspname='public' AND c.relkind IN ('r','p') AND a.attacl IS NOT NULL AND (x.grantee=0 OR pg_catalog.pg_get_userbyid(x.grantee) IN ('anon','authenticated','service_role'))), agg AS (SELECT count(*)::int AS n,coalesce(jsonb_agg(obj ORDER BY obj::text COLLATE "C"),'[]'::jsonb) AS j FROM rows) SELECT jsonb_build_object('class','public_column_acl','count',n,'md5',md5(j::text)) AS result FROM agg;

-- CLASS: public_function_definitions
WITH rows AS (SELECT jsonb_build_object('identity',p.proname||'('||pg_catalog.pg_get_function_identity_arguments(p.oid)||')','definition',pg_catalog.pg_get_functiondef(p.oid),'owner',pg_catalog.pg_get_userbyid(p.proowner),'security_definer',p.prosecdef,'settings',p.proconfig) AS obj FROM pg_catalog.pg_proc p JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public'), agg AS (SELECT count(*)::int AS n,coalesce(jsonb_agg(obj ORDER BY obj::text COLLATE "C"),'[]'::jsonb) AS j FROM rows) SELECT jsonb_build_object('class','public_function_definitions','count',n,'md5',md5(j::text)) AS result FROM agg;

-- CLASS: public_function_acl
WITH rows AS (SELECT jsonb_build_object('function',p.proname||'('||pg_catalog.pg_get_function_identity_arguments(p.oid)||')','grantee',CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_catalog.pg_get_userbyid(a.grantee) END,'grantor',pg_catalog.pg_get_userbyid(a.grantor),'privilege',a.privilege_type,'grantable',a.is_grantable) AS obj FROM pg_catalog.pg_proc p JOIN pg_catalog.pg_namespace n ON n.oid=p.pronamespace CROSS JOIN LATERAL pg_catalog.aclexplode(coalesce(p.proacl,pg_catalog.acldefault('f',p.proowner))) a WHERE n.nspname='public' AND (a.grantee=0 OR pg_catalog.pg_get_userbyid(a.grantee) IN ('anon','authenticated','service_role'))), agg AS (SELECT count(*)::int AS n,coalesce(jsonb_agg(obj ORDER BY obj::text COLLATE "C"),'[]'::jsonb) AS j FROM rows) SELECT jsonb_build_object('class','public_function_acl','count',n,'md5',md5(j::text)) AS result FROM agg;

-- CLASS: public_triggers
WITH rows AS (SELECT jsonb_build_object('table',c.relname,'name',t.tgname,'enabled',t.tgenabled,'definition',pg_catalog.pg_get_triggerdef(t.oid,true),'function',t.tgfoid::regprocedure::text) AS obj FROM pg_catalog.pg_trigger t JOIN pg_catalog.pg_class c ON c.oid=t.tgrelid JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND NOT t.tgisinternal), agg AS (SELECT count(*)::int AS n,coalesce(jsonb_agg(obj ORDER BY obj::text COLLATE "C"),'[]'::jsonb) AS j FROM rows) SELECT jsonb_build_object('class','public_triggers','count',n,'md5',md5(j::text)) AS result FROM agg;

-- CLASS: event_triggers
WITH rows AS (SELECT jsonb_build_object('name',e.evtname,'event',e.evtevent,'tags',e.evttags,'enabled',e.evtenabled,'function',e.evtfoid::regprocedure::text,'owner',pg_catalog.pg_get_userbyid(e.evtowner)) AS obj FROM pg_catalog.pg_event_trigger e), agg AS (SELECT count(*)::int AS n,coalesce(jsonb_agg(obj ORDER BY obj::text COLLATE "C"),'[]'::jsonb) AS j FROM rows) SELECT jsonb_build_object('class','event_triggers','count',n,'md5',md5(j::text)) AS result FROM agg;

-- CLASS: public_views
WITH rows AS (SELECT jsonb_build_object('name',c.relname,'kind',c.relkind,'definition',pg_catalog.pg_get_viewdef(c.oid,true),'owner',pg_catalog.pg_get_userbyid(c.relowner)) AS obj FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='public' AND c.relkind IN ('v','m')), agg AS (SELECT count(*)::int AS n,coalesce(jsonb_agg(obj ORDER BY obj::text COLLATE "C"),'[]'::jsonb) AS j FROM rows) SELECT jsonb_build_object('class','public_views','count',n,'md5',md5(j::text)) AS result FROM agg;

-- CLASS: extensions
WITH rows AS (SELECT jsonb_build_object('name',e.extname,'version',e.extversion,'schema',n.nspname) AS obj FROM pg_catalog.pg_extension e JOIN pg_catalog.pg_namespace n ON n.oid=e.extnamespace), agg AS (SELECT count(*)::int AS n,coalesce(jsonb_agg(obj ORDER BY obj::text COLLATE "C"),'[]'::jsonb) AS j FROM rows) SELECT jsonb_build_object('class','extensions','count',n,'md5',md5(j::text)) AS result FROM agg;

-- CLASS: storage_buckets
WITH rows AS (SELECT jsonb_build_object('id',b.id,'name',b.name,'public',b.public,'avif_autodetection',b.avif_autodetection,'file_size_limit',b.file_size_limit,'allowed_mime_types',b.allowed_mime_types,'type',b.type::text,'versioning_status',b.versioning_status,'lifecycle_configuration',b.lifecycle_configuration) AS obj FROM storage.buckets b), agg AS (SELECT count(*)::int AS n,coalesce(jsonb_agg(obj ORDER BY obj::text COLLATE "C"),'[]'::jsonb) AS j FROM rows) SELECT jsonb_build_object('class','storage_buckets','count',n,'md5',md5(j::text)) AS result FROM agg;

-- CLASS: storage_objects_policies
WITH rows AS (SELECT jsonb_build_object('name',p.policyname,'permissive',p.permissive,'roles',p.roles,'command',p.cmd,'using',p.qual,'with_check',p.with_check) AS obj FROM pg_catalog.pg_policies p WHERE p.schemaname='storage' AND p.tablename='objects'), agg AS (SELECT count(*)::int AS n,coalesce(jsonb_agg(obj ORDER BY obj::text COLLATE "C"),'[]'::jsonb) AS j FROM rows) SELECT jsonb_build_object('class','storage_objects_policies','count',n,'md5',md5(j::text)) AS result FROM agg;

-- CLASS: storage_objects_acl
WITH rows AS (SELECT jsonb_build_object('table',c.relname,'grantee',CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_catalog.pg_get_userbyid(a.grantee) END,'grantor',pg_catalog.pg_get_userbyid(a.grantor),'privilege',a.privilege_type,'grantable',a.is_grantable) AS obj FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace CROSS JOIN LATERAL pg_catalog.aclexplode(c.relacl) a WHERE n.nspname='storage' AND c.relname='objects' AND (a.grantee=0 OR pg_catalog.pg_get_userbyid(a.grantee) IN ('anon','authenticated','service_role'))), agg AS (SELECT count(*)::int AS n,coalesce(jsonb_agg(obj ORDER BY obj::text COLLATE "C"),'[]'::jsonb) AS j FROM rows) SELECT jsonb_build_object('class','storage_objects_acl','count',n,'md5',md5(j::text)) AS result FROM agg;

-- CLASS: storage_objects_triggers
WITH rows AS (SELECT jsonb_build_object('table',c.relname,'name',t.tgname,'enabled',t.tgenabled,'definition',pg_catalog.pg_get_triggerdef(t.oid,true),'function',t.tgfoid::regprocedure::text) AS obj FROM pg_catalog.pg_trigger t JOIN pg_catalog.pg_class c ON c.oid=t.tgrelid JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='storage' AND c.relname='objects' AND NOT t.tgisinternal), agg AS (SELECT count(*)::int AS n,coalesce(jsonb_agg(obj ORDER BY obj::text COLLATE "C"),'[]'::jsonb) AS j FROM rows) SELECT jsonb_build_object('class','storage_objects_triggers','count',n,'md5',md5(j::text)) AS result FROM agg;

-- CLASS: auth_users_triggers
WITH rows AS (SELECT jsonb_build_object('name',t.tgname,'enabled',t.tgenabled,'definition',pg_catalog.pg_get_triggerdef(t.oid,true),'function',t.tgfoid::regprocedure::text) AS obj FROM pg_catalog.pg_trigger t JOIN pg_catalog.pg_class c ON c.oid=t.tgrelid JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname='auth' AND c.relname='users' AND NOT t.tgisinternal), agg AS (SELECT count(*)::int AS n,coalesce(jsonb_agg(obj ORDER BY obj::text COLLATE "C"),'[]'::jsonb) AS j FROM rows) SELECT jsonb_build_object('class','auth_users_triggers','count',n,'md5',md5(j::text)) AS result FROM agg;

-- CLASS: public_sequences
WITH rows AS (SELECT jsonb_build_object('name',s.relname,'type',pg_catalog.format_type(q.seqtypid,NULL),'start',q.seqstart,'increment',q.seqincrement,'min',q.seqmin,'max',q.seqmax,'cache',q.seqcache,'cycle',q.seqcycle,'owned_table',owner_table.relname,'owned_column',owner_col.attname,'ownership_kind',dep.deptype,'owner',pg_catalog.pg_get_userbyid(s.relowner)) AS obj FROM pg_catalog.pg_class s JOIN pg_catalog.pg_namespace n ON n.oid=s.relnamespace JOIN pg_catalog.pg_sequence q ON q.seqrelid=s.oid LEFT JOIN pg_catalog.pg_depend dep ON dep.objid=s.oid AND dep.classid='pg_class'::regclass AND dep.refclassid='pg_class'::regclass AND dep.deptype IN ('a','i') LEFT JOIN pg_catalog.pg_class owner_table ON owner_table.oid=dep.refobjid LEFT JOIN pg_catalog.pg_attribute owner_col ON owner_col.attrelid=dep.refobjid AND owner_col.attnum=dep.refobjsubid WHERE n.nspname='public' AND s.relkind='S'), agg AS (SELECT count(*)::int AS n,coalesce(jsonb_agg(obj ORDER BY obj::text COLLATE "C"),'[]'::jsonb) AS j FROM rows) SELECT jsonb_build_object('class','public_sequences','count',n,'md5',md5(j::text)) AS result FROM agg;

-- CLASS: public_schema_acl
WITH rows AS (SELECT jsonb_build_object('grantee',CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_catalog.pg_get_userbyid(a.grantee) END,'grantor',pg_catalog.pg_get_userbyid(a.grantor),'privilege',a.privilege_type,'grantable',a.is_grantable) AS obj FROM pg_catalog.pg_namespace n CROSS JOIN LATERAL pg_catalog.aclexplode(n.nspacl) a WHERE n.nspname='public' AND (a.grantee=0 OR pg_catalog.pg_get_userbyid(a.grantee) IN ('anon','authenticated','service_role'))), agg AS (SELECT count(*)::int AS n,coalesce(jsonb_agg(obj ORDER BY obj::text COLLATE "C"),'[]'::jsonb) AS j FROM rows) SELECT jsonb_build_object('class','public_schema_acl','count',n,'md5',md5(j::text)) AS result FROM agg;

-- CLASS: storage_schema_acl
WITH rows AS (SELECT jsonb_build_object('grantee',CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_catalog.pg_get_userbyid(a.grantee) END,'grantor',pg_catalog.pg_get_userbyid(a.grantor),'privilege',a.privilege_type,'grantable',a.is_grantable) AS obj FROM pg_catalog.pg_namespace n CROSS JOIN LATERAL pg_catalog.aclexplode(n.nspacl) a WHERE n.nspname='storage' AND (a.grantee=0 OR pg_catalog.pg_get_userbyid(a.grantee) IN ('anon','authenticated','service_role'))), agg AS (SELECT count(*)::int AS n,coalesce(jsonb_agg(obj ORDER BY obj::text COLLATE "C"),'[]'::jsonb) AS j FROM rows) SELECT jsonb_build_object('class','storage_schema_acl','count',n,'md5',md5(j::text)) AS result FROM agg;

-- CLASS: public_default_acl
WITH rows AS (SELECT jsonb_build_object('creator',pg_catalog.pg_get_userbyid(d.defaclrole),'schema',n.nspname,'object_kind',d.defaclobjtype,'grantee',CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_catalog.pg_get_userbyid(a.grantee) END,'privilege',a.privilege_type,'grantable',a.is_grantable) AS obj FROM pg_catalog.pg_default_acl d LEFT JOIN pg_catalog.pg_namespace n ON n.oid=d.defaclnamespace CROSS JOIN LATERAL pg_catalog.aclexplode(d.defaclacl) a WHERE n.nspname='public' AND pg_catalog.pg_get_userbyid(d.defaclrole) IN ('postgres','supabase_admin')), agg AS (SELECT count(*)::int AS n,coalesce(jsonb_agg(obj ORDER BY obj::text COLLATE "C"),'[]'::jsonb) AS j FROM rows) SELECT jsonb_build_object('class','public_default_acl','count',n,'md5',md5(j::text)) AS result FROM agg;

-- CLASS: public_sequence_acl
WITH rows AS (SELECT jsonb_build_object('sequence',c.relname,'grantee',CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE pg_catalog.pg_get_userbyid(a.grantee) END,'grantor',pg_catalog.pg_get_userbyid(a.grantor),'privilege',a.privilege_type,'grantable',a.is_grantable) AS obj FROM pg_catalog.pg_class c JOIN pg_catalog.pg_namespace n ON n.oid=c.relnamespace CROSS JOIN LATERAL pg_catalog.aclexplode(c.relacl) a WHERE n.nspname='public' AND c.relkind='S' AND (a.grantee=0 OR pg_catalog.pg_get_userbyid(a.grantee) IN ('anon','authenticated','service_role'))), agg AS (SELECT count(*)::int AS n,coalesce(jsonb_agg(obj ORDER BY obj::text COLLATE "C"),'[]'::jsonb) AS j FROM rows) SELECT jsonb_build_object('class','public_sequence_acl','count',n,'md5',md5(j::text)) AS result FROM agg;
